import{_ as o}from"./chunks/100.I7A0VXqr.js";import{_ as i,o as r,c as n,ak as a}from"./chunks/framework.DC-k2h36.js";const s="/projects/esp32Sensor/en/latest/assets/1.Bq5PlzZX.webp",l="/projects/esp32Sensor/en/latest/assets/2.BynGFXNU.webp",e="/projects/esp32Sensor/en/latest/assets/3.DQKoropV.webp",c="/projects/esp32Sensor/en/latest/assets/4.Cz6u0qQt.webp",d="/projects/esp32Sensor/en/latest/assets/5.BdKWJSpl.webp",p="/projects/esp32Sensor/en/latest/assets/4.Xm1ewtlL.webp",h="/projects/esp32Sensor/en/latest/assets/7.CJ4G3_9w.webp",g="/projects/esp32Sensor/en/latest/assets/8.B7Q44vnr.webp",m="/projects/esp32Sensor/en/latest/assets/9.Dn0OWb3G.webp",u="/projects/esp32Sensor/en/latest/assets/10.DOjy08NJ.webp",_="/projects/esp32Sensor/en/latest/assets/11.CW1SKy4b.webp",y="/projects/esp32Sensor/en/latest/assets/12.CTm8gXic.webp",f="/projects/esp32Sensor/en/latest/assets/13.CWjGoygI.webp",w="/projects/esp32Sensor/en/latest/assets/14.Kd4nFJXC.webp",b="/projects/esp32Sensor/en/latest/assets/15.5H_LWQh4.webp",x="/projects/esp32Sensor/en/latest/assets/16.Cw-LRSGS.webp",q="/projects/esp32Sensor/en/latest/assets/17.Deakagdb.webp",z=JSON.parse('{"title":"20. AI Voice Interaction Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/20. AI Voice Interaction Module.md","filePath":"docs/20. AI Voice Interaction Module.md"}'),v={name:"docs/20. AI Voice Interaction Module.md"};function k(I,t,P,T,S,A){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_20-ai-voice-interaction-module" tabindex="-1">20. AI Voice Interaction Module <a class="header-anchor" href="#_20-ai-voice-interaction-module" aria-label="Permalink to &quot;20. AI Voice Interaction Module&quot;">​</a></h1><h2 id="_20-1-introduction" tabindex="-1">20.1 Introduction <a class="header-anchor" href="#_20-1-introduction" aria-label="Permalink to &quot;20.1 Introduction&quot;">​</a></h2><p>The AI voice interaction module recognizes and speaks words using the CI1302 chip. It includes offline neural network acceleration and dedicated speech processing hardware, using noise cancellation and deep learning models to process audio and recognize voice commands quickly. The module operates with a voice wake-up system, requiring the wake-up word before it begins listening for commands.</p><p>With easy setup and accurate speech recognition, this module works great for smart homes, conversational bots, educational robots, and smart vehicle projects.</p><img loading="lazy" height="1387" width="1387" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_20-2-technical-specifications" tabindex="-1">20.2 Technical Specifications <a class="header-anchor" href="#_20-2-technical-specifications" aria-label="Permalink to &quot;20.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Recognition mode</td><td style="text-align:center;">Command wake-up</td></tr><tr><td style="text-align:center;">Recognition range</td><td style="text-align:center;">1–5 m</td></tr><tr><td style="text-align:center;">Command capacity</td><td style="text-align:center;">≤255 words or short phrases</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">55.4 × 23.4 × 21.0 mm</td></tr></tbody></table><h2 id="_20-3-hardware-interface-description" tabindex="-1">20.3 Hardware Interface Description <a class="header-anchor" href="#_20-3-hardware-interface-description" aria-label="Permalink to &quot;20.3 Hardware Interface Description&quot;">​</a></h2><img loading="lazy" height="650" width="1330" src="'+l+'" class="common_img" style="width:500px;"><p>The corresponding functions are outlined in the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Component Name</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;">Type-C port</td><td style="text-align:left;">Connects to a computer for flashing module firmware</td></tr><tr><td style="text-align:center;">Reset button</td><td style="text-align:left;">Restarts the module upon pressing to resolve program halts or abnormal operation</td></tr><tr><td style="text-align:center;">Speaker</td><td style="text-align:left;">Plays back audio and broadcasts voice responses</td></tr><tr><td style="text-align:center;">Microphone</td><td style="text-align:left;">Captures ambient audio for speech recognition</td></tr><tr><td style="text-align:center;">Blue signal indicator LED</td><td style="text-align:left;">Remains solidly illuminated under normal conditions and flashes once upon recognizing a command word</td></tr><tr><td style="text-align:center;">Red power indicator LED</td><td style="text-align:left;">Remains solidly illuminated when power supply is normal</td></tr><tr><td style="text-align:center;">Module cable port</td><td style="text-align:left;">Supports a 4-pin module cable for power supply and signal communication with the controller</td></tr></tbody></table><h2 id="_20-4-voice-interaction-testing" tabindex="-1">20.4 Voice Interaction Testing <a class="header-anchor" href="#_20-4-voice-interaction-testing" aria-label="Permalink to &quot;20.4 Voice Interaction Testing&quot;">​</a></h2><ol><li>Connect the Type-C port of the AI voice interaction module to a computer port or a phone charger using a USB cable for power supply.</li></ol><img loading="lazy" height="800" width="2041" src="'+e+'" class="common_img" style="width:500px;"><ol start="2"><li>Testing voice interaction with the command <strong>Go straight</strong> serves as an example. First, speak the wake-up word <strong>Hello Hiwonder</strong> to wake up the module. When the module replies <strong>I&#39;m here</strong>, it is ready to recognize commands.</li></ol><img loading="lazy" height="639" width="1000" src="'+c+'" class="common_img" style="width:400px;"><ol start="3"><li>Next, say the command <strong>Go straight</strong> to hear the corresponding voice reply.</li></ol><img loading="lazy" height="648" width="1094" src="'+d+'" class="common_img" style="width:400px;"><ol start="4"><li>The module also responds to the following voice commands, triggering spoken replies from WonderEcho.</li></ol><img loading="lazy" height="531" width="802" src="'+p+'" class="common_img" style="width:500px;"><h2 id="_20-5-hands-on-project" tabindex="-1">20.5 Hands-On Project <a class="header-anchor" href="#_20-5-hands-on-project" aria-label="Permalink to &quot;20.5 Hands-On Project&quot;">​</a></h2><h3 id="_20-5-1-project-overview" tabindex="-1">20.5.1 Project Overview <a class="header-anchor" href="#_20-5-1-project-overview" aria-label="Permalink to &quot;20.5.1 Project Overview&quot;">​</a></h3><p>This project uses the AI voice interaction module to listen for voice commands in a continuous loop and print matching messages to the console. It covers module setup, reading speech recognition data, and using multi-branch conditional statements.</p><h3 id="_20-5-2-hardware-wiring" tabindex="-1">20.5.2 Hardware Wiring <a class="header-anchor" href="#_20-5-2-hardware-wiring" aria-label="Permalink to &quot;20.5.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the AI voice interaction module to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="882" src="'+h+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_20-5-3-adding-extensions" tabindex="-1">20.5.3 Adding Extensions <a class="header-anchor" href="#_20-5-3-adding-extensions" aria-label="Permalink to &quot;20.5.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>WonderEcho voice module</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+g+'" class="common_img" style="width:800px;"><h3 id="_20-5-4-complete-program-and-analysis" tabindex="-1">20.5.4 Complete Program and Analysis <a class="header-anchor" href="#_20-5-4-complete-program-and-analysis" aria-label="Permalink to &quot;20.5.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the AI voice interaction module is initialized to port P1.</p></li><li><p>Inside the main program loop, the recognized word ID is stored into variable <code>result</code> to perform multi-branch conditional judgment:</p><ul><li><p>If <code>result</code> = 1, corresponding to the &quot;Go straight&quot; command, the program prints &quot;Go forward!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 2, corresponding to the &quot;Go backward&quot; command, the program prints &quot;Go back!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 3, corresponding to the &quot;Turn left&quot; command, the program prints &quot;Turning left!&quot; to the serial monitor.</p></li><li><p>If <code>result</code> = 4, corresponding to the &quot;Turn right&quot; command, the program prints &quot;Turning right!&quot; to the serial monitor.</p></li><li><p>Under all other conditions, the program prints &quot;Reading...&quot; to the serial monitor.</p></li></ul></li><li><p>A 0.5 s delay at the end of each loop iteration regulates data polling rate and maintains stable serial output.</p></li></ol><img loading="lazy" height="1131" width="775" src="'+m+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/20 AI Voice Module.sb3</a>.</strong></p></div><h3 id="_20-5-5-program-upload" tabindex="-1">20.5.5 Program Upload <a class="header-anchor" href="#_20-5-5-program-upload" aria-label="Permalink to &quot;20.5.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+o+'" class="common_img" style="width:800px;"><h3 id="_20-5-6-program-outcome" tabindex="-1">20.5.6 Program Outcome <a class="header-anchor" href="#_20-5-6-program-outcome" aria-label="Permalink to &quot;20.5.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, check the serial monitor in the lower-right corner of the programming software. Wake up the module, then say &quot;Go straight&quot; to display &quot;Go forward!&quot; in the console. Saying &quot;Go backward&quot; displays &quot;Go back!&quot;, saying &quot;Turn left&quot; displays &quot;Turning left!&quot;, and saying &quot;Turn right&quot; displays &quot;Turning right!&quot;. The module continues listening for voice commands in a continuous loop.</p><img loading="lazy" height="956" width="1119" src="'+u+'" class="common_img" style="width:500px;"><h2 id="_20-6-firmware-update" tabindex="-1">20.6 Firmware Update <a class="header-anchor" href="#_20-6-firmware-update" aria-label="Permalink to &quot;20.6 Firmware Update&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module comes pre-flashed with factory firmware and does not require re-flashing under normal conditions. This guide is intended only for firmware updates or recovery from corrupted firmware.</strong></p></div><ol><li>Connect the Type-C port on top of the AI voice interaction module to a computer using a USB cable.</li></ol><img loading="lazy" height="800" width="2041" src="'+e+'" class="common_img" style="width:500px;"><ol start="2"><li>Open the <strong>PACK_UPDATE_TOOL</strong> application located in the <strong><a href="https://drive.google.com/drive/folders/1TS862PGKSa4wgwTuiq-I3VYZfSjo8TQq?usp=sharing" target="_blank" rel="noreferrer">Appendix/02 AI Voice Interaction Module/01 Flashing Tool</a></strong> directory.</li></ol><img loading="lazy" height="395" width="669" src="'+_+'" class="common_img" style="width:500px;"><ol start="3"><li>Select the <strong>CI1302</strong> chip from the dropdown menu, then click <strong>Update</strong>.</li></ol><img loading="lazy" height="492" width="652" src="'+y+'" class="common_img" style="width:500px;"><ol start="4"><li>Click <strong>Select firmware</strong> to choose the bin file for flashing, then select the <strong>WonderEcho Flash‑firmware 20260901.bin</strong> file located in the <strong><a href="https://drive.google.com/drive/folders/1_M0Q7Y5_S_nhoDtN_dbLKPoxoPE--ILM?usp=sharing" target="_blank" rel="noreferrer">Appendix/02 AI Voice Interaction Module/02 Firmware</a></strong> directory.</li></ol><img loading="lazy" height="248" width="836" src="'+f+'" class="common_img" style="width:500px;"><img loading="lazy" height="47" width="479" src="'+w+'" class="common_img" style="width:500px;"><ol start="5"><li>Locate the corresponding COM port and click to select its checkbox.</li></ol><img loading="lazy" height="633" width="843" src="'+b+'" class="common_img" style="width:500px;"><ol start="6"><li>Press the <strong>RST</strong> button on the AI voice interaction module to enter flashing mode, then wait for the update to complete successfully.</li></ol><img loading="lazy" height="762" width="1641" src="'+x+'" class="common_img" style="width:400px;"><img loading="lazy" height="217" width="838" src="'+q+'" class="common_img" style="width:500px;">',56)])])}const O=i(v,[["render",k]]);export{z as __pageData,O as default};
